fn read(&self, key: &str) -> Arc<Value> {
    if let Some(e) = self.map.lock().unwrap().get(key) {          // cache hit
        if e.deadline > Instant::now() { return Arc::clone(&e.value); }
    }
    let value = Arc::new(self.source.read(key));                  // lock released: safe across I/O
    let mut map = self.map.lock().unwrap();
    map.insert(key.to_string(),
               Entry { value: Arc::clone(&value), deadline: Instant::now() + self.ttl });
    value
}
